-- Rifts World Book 11: Coalition War Campaign - its weapons and body armor.
-- Twenty new rows from the CS Weapons & Equipment chapter, printed 89-103:
-- eleven small arms and heavy weapons, the micro-fusion rifle grenade, the
-- giant vibro-sword, six new "Dead Boy" body armors and the CAJ-5 weapon arm.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-cwc-gear.sql
--
-- ALL 20 ARE NEW - catalog-diff --table gear --remote, 2026-09-25, against
-- 2900 rows, every "missing" nearest hand-checked. What this book ALSO prints
-- and is NOT added here, because the catalog already holds it:
--   * C-10, C-12, C-18, Neural Mace, Vibro-Knife/Saber/Sword/Claws, CA-1/CA-2,
--     the Dog Pack spikes and DPM riot armor - all from Rifts Ultimate
--     Edition, the LATER book, so RUE's rows stand.
--   * Fusion Blocks (Light/Medium/Heavy), Stun/Flash and Tear Gas grenades,
--     the hand-held and parachute flares - held from Triax with the same
--     figures.
--   * C-14, C-27 and the explosive, fragmentation and smoke grenades exist as
--     ESTIMATE or web-reference rows. This book prices them, and
--     zzzzzzzzzzzzz-cwc-fill-estimate-gear.sql fills them; it has to sort
--     after zzzzzzzzzzzz-dupes-pass-cross-system-gear.sql, which writes them.
--   * The missile chart (printed 97) has no row equivalent; nothing here
--     models missiles as items.
--
-- EVERY NUMBER WAS READ OFF A 200 DPI RENDER of printed 88-105, not the text
-- layer, which carries this book's digit cipher (`!D6xlO` for 1D6x10, `6Q.6`
-- for 6D6) and welds printed 89 (the C-5) into one column.
--
-- CONVENTIONS:
--   * Weapons are 'weapon', including the CAJ-5 arm; the armors are 'armor'.
--   * A range the book prices stores the low end in cost and the rest in
--     cost_note. The power armor weapons (CTT-P40, CTT-M20) and every armor
--     print no price: cost is NULL, as the gear schema says a finished
--     unpriced row is.
--   * An armor's main body M.D.C. is in mdc; every location is in the
--     description, as the RUE CA-1/CA-2 rows do.
--   * Three misprints are recorded rather than corrected in a number column:
--     the C-5's 800 feet printed as 224 m, and the C-27's and C-29's metric
--     ranges printed in km.
--   * Descriptions are short paraphrases; no sentence is the book's.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('c-5-pump-pistol', 'C-5 Pump Pistol', 'rifts', 'weapon', 5, 10000, 'Market cost 10,000 credits for the gun and 400 credits per round; fair availability. A speed loader costs 1,200 credits.', '4D6 M.D.', 1, '800 feet (the book prints 224 m)', '5 rounds, loaded one at a time; a speed loader loads all five in one melee action (4 seconds)', 'Standard', NULL, NULL, NULL, 'A Coalition pump-action pistol that fires small high-explosive rounds one at a time; prized for putting all its damage into a one-foot blast. Carried mainly by commandos, Special Forces and some field officers, and widely by the ISS.', 'Rifts World Book 11: Coalition War Campaign p.89-90'),
('c-20-laser-pistol', 'C-20 Laser Pistol', 'rifts', 'weapon', 3.5, 16000, 'Black Market cost 16,000 credits.', '2D6 M.D.', 1, '800 feet (244 m)', '21 shots per standard E-Clip, 30 per long E-Clip', 'Standard', NULL, NULL, NULL, 'The new standard-issue Coalition sidearm, replacing the C-18: light, well balanced and harder hitting.', 'Rifts World Book 11: Coalition War Campaign p.90'),
('cp-30-laser-pulse-pistol', 'CP-30 Laser Pulse Pistol', 'rifts', 'weapon', 4, 26000, 'Black Market cost 26,000 credits for the weapon; 90,000 for the portable energy generator.', '2D4 M.D. single blast, or 4D6 M.D. per triple pulse', 1, '600 feet (183 m)', '21 single shots (7 pulses) per standard E-Clip, 30 (10) per long E-Clip; a cable to a hip or backpack energy canister gives 72 single or 24 triple blasts (canister and pack 4 lbs)', 'Equal to the user''s hand to hand attacks (usually 3-6)', NULL, NULL, NULL, 'A multi-pulse Coalition pistol for heavy close-combat firepower, issued to officers, special operatives and ISS monster hunters. Laser targeting: +1 to strike on an aimed shot.', 'Rifts World Book 11: Coalition War Campaign p.90'),
('cp-40-pulse-laser-rifle', 'CP-40 Pulse Laser Rifle', 'rifts', 'weapon', 9, 40000, 'Black Market cost 40,000 credits; a hot commodity, not commonly available.', '2D6 M.D. single blast or 6D6 M.D. per triple pulse; S.D.C. settings 3D6 single or 1D6x10 per pulse', 1, '2000 feet (610 m)', '21 blasts (7 pulses) per standard E-Clip, 30 (10) per long E-Clip; a canister pack gives 60 single or 20 triple blasts. Thirty S.D.C. blasts or six S.D.C. pulses use the energy of one M.D. blast', 'Equal to the user''s hand to hand attacks (usually 3-6); each shot or pulse is one attack', NULL, NULL, NULL, 'The new standard Coalition infantry rifle: a pulse laser with four damage settings, a passive nightvision scope and laser targeting.', 'Rifts World Book 11: Coalition War Campaign p.92'),
('cp-50-dragonfire-assault-rifle', 'CP-50 "Dragonfire" Assault Rifle', 'rifts', 'weapon', 10, 50000, 'Black Market cost 50,000 credits; a hot commodity. Rifle grenades 550 credits each or 4,500 a dozen; micro-fusion grenades 1,500-3,000 each and extremely rare.', 'Laser 2D6 M.D. single or 6D6 M.D. per triple pulse; grenade 2D6 M.D. to a 12 foot (3.6 m) area, or micro-fusion 6D6 M.D. to a 12 foot diameter', 1, 'Laser 2000 feet (610 m); grenade launcher 1200 feet (365 m)', 'Laser 21 blasts (7 pulses) per standard E-Clip, 30 (10) per long E-Clip, or a canister pack as the CP-40; grenade launcher 12, plus 24-48 in a satchel or 12 on a bandoleer', 'Laser equal to the user''s hand to hand attacks; grenades one aimed per attack or four in rapid succession', NULL, NULL, NULL, 'The successor to the C-14: a pulse laser rifle with a pump-action grenade launcher under the barrel, able to fire the new micro-fusion grenades. Reloading the launcher takes a full melee round.', 'Rifts World Book 11: Coalition War Campaign p.92-93'),
('c-29-hellfire-plasma-cannon', 'C-29 "Hellfire" Heavy Plasma Cannon', 'rifts', 'weapon', 12, 32000, 'Black Market cost 32,000 credits for the rifle; it takes only an E-Clip Canister, 10,000 credits new and loaded, 2,000 to recharge. The book prints the same price block as the C-27.', '1D6x10 M.D.', 1, '1400 feet (the book prints 423 km)', '8 blasts per top-mounted energy canister; 16 with a second canister on a hip or backpack pack', 'Equal to the user''s attacks per melee; each blast is one attack', NULL, NULL, NULL, 'A new heavy plasma cannon for anti-armor work: formidable damage at short range. Targeting scope: +1 to strike on an aimed shot. Dual backpacks and 2-4 spare canisters are commonly issued.', 'Rifts World Book 11: Coalition War Campaign p.93-94'),
('cv-212-variable-frequency-laser-rifle', 'CV-212 Variable Light Frequency Laser Rifle', 'rifts', 'weapon', 8, 50000, 'Black Market cost 50,000 credits; standard E-Clip 5,000 new, 1,500 to recharge; E-Clip canister 10,000 new, 2,000 to recharge.', '2D6 M.D. single or 6D6 M.D. per triple burst; S.D.C. setting 6D6', 1, '2000 feet (610 m)', '21 blasts (7 pulses) per standard E-Clip, 30 (10) per long E-Clip; a canister pack gives 60 single or 20 triple blasts. Six S.D.C. shots equal one M.D. blast', 'Equal to the user''s hand to hand attacks', NULL, NULL, NULL, 'A laser rifle whose computer analyzer shifts its frequency to defeat laser-resistant armor such as a Glitter Boy''s. Attacks in the first melee round against such armor do half damage; after one round the analyzer adjusts. M.D. damage to the rifle has an 80% chance to knock the analyzer out, needing 1D4 melee rounds of manual adjustment. Laser targeting: +1 to strike on an aimed shot. Skelebots are typically issued it with a dual backpack. The book also calls it the C-212 once.', 'Rifts World Book 11: Coalition War Campaign p.94'),
('ctt-p40-particle-beam-cannon', 'CTT-P40 Particle Beam Cannon', 'rifts', 'weapon', 89, NULL, 'No price given; a power armor weapon.', '1D6x10 M.D.', 1, '2000 feet (610 m)', '40 blasts; the back half of the weapon is a rechargeable energy cell', 'Equal to the user''s hand to hand attacks', NULL, NULL, NULL, 'A giant particle beam rifle sized for power armor: standard for the Striker SAMAS, also used by Terror Troopers and full conversion cyborgs. A top-mounted box carries laser targeting and a 20x nightvision scope (3000 ft). One-handed use needs P.S. 24 and is -2 to strike unless in Terror Trooper or Super SAMAS armor.', 'Rifts World Book 11: Coalition War Campaign p.95'),
('ctt-m20-missile-rifle', 'CTT-M20 Missile Rifle', 'rifts', 'weapon', 110, NULL, 'No price given; a power armor weapon.', 'Mini-missiles by type, usually armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.; mounted laser 2D6 M.D.', 1, 'Mini-missiles about 1 mile (1.6 km); laser 2000 feet (610 m)', '20 mini-missiles, 10 per launch tube; the laser takes a standard (20 shots) or long (30 shots) E-Clip', 'Missiles one at a time or in volleys of two or four', NULL, NULL, NULL, 'A twin-tube mini-missile rifle built for the Terror Trooper power armor and also carried by SAMAS pilots and cyborgs. Weighs about 30 lbs less unloaded. The box laser''s lower port is a targeting sight: +1 to strike. One-handed use needs P.S. 24 and is -2 to strike unless in Terror Trooper or Super SAMAS armor or with P.S. 36.', 'Rifts World Book 11: Coalition War Campaign p.95'),
('cr-1-rocket-launcher', 'CR-1 Rocket Launcher', 'rifts', 'weapon', 14, 18000, 'Black Market cost 18,000 credits for the launcher; mini-missiles 1,000 each (light, 5D6 M.D.) or 2,200 each (plasma or armor piercing).', 'By mini-missile, usually 1D4x10 M.D. (armor piercing) or 1D6x10 M.D. (plasma)', 1, 'One mile (1.6 km)', 'Single-shot; carried in a side-pack of 6 (10 lbs), a backpack of 12, or a 24-missile case (10 M.D.C., 40 lbs)', 'One per melee for a single operator; three per melee for a two-man team', NULL, NULL, NULL, 'The older Coalition shoulder launcher for single mini-missiles, reusable, with a multi-optic scope: telescopic (x20, 2 miles), infrared and passive nightvision (2000 ft) and laser targeting. Each missile weighs about 1 lb.', 'Rifts World Book 11: Coalition War Campaign p.96'),
('c-200-dead-mans-rail-gun', 'C-200 "Dead Man''s" Rail Gun', 'rifts', 'weapon', 45, 80000, 'Black Market cost 80,000 credits; poor availability.', '4D6 M.D. per 20-round burst; 1D4 M.D. per single round', 1, '4000 feet (1200 m)', 'Short clip 200 rounds (10 bursts, 10 lbs); light drum 600 rounds (30 bursts, 30 lbs); heavy belt-fed drum 2000 rounds (100 bursts, 100 lbs) for cyborgs and robots', 'Equal to the user''s hand to hand attacks (usually 3-6)', NULL, NULL, NULL, 'A light, general-purpose Coalition rail gun for power armor and exoskeleton troops, cyborgs and very strong characters. Handling a drum needs P.S. 24; reloading one takes about 3 minutes, or 30 seconds for a trained field mechanic. The infantry version carries laser targeting, telescopic and nightvision scopes (6000 ft); a robot''s carries laser targeting only. Targeting: +1 to strike.', 'Rifts World Book 11: Coalition War Campaign p.96'),
('micro-fusion-rifle-grenade', 'Micro-Fusion Rifle Grenade', 'rifts', 'weapon', NULL, 1500, '1,500-3,000 credits each; extremely rare.', '6D6 M.D. to a 12 foot (3.6 m) diameter blast', 1, '1200 feet (365 m) from a CP-50 launcher', NULL, NULL, NULL, NULL, NULL, 'A new Coalition rifle grenade fired from the CP-50 "Dragonfire" launcher. It exists only as a launched round, not as a hand grenade.', 'Rifts World Book 11: Coalition War Campaign p.92-93, 98'),
('giant-vibro-sword', 'Giant Vibro-Sword', 'rifts', 'weapon', NULL, 18000, 'Market cost 18,000 credits.', '3D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'An oversized vibro-blade sword, usually wielded by power armor or giant robot vehicles.', 'Rifts World Book 11: Coalition War Campaign p.99'),
('ca-3-light-dead-boy-armor', 'CA-3 Light Dead Boy Armor', 'rifts', 'armor', 12, NULL, 'Not available; exclusive to the CS military.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 80, 'The lightest of the new-style Coalition "Dead Boy" armors, worn by female troopers, scouts and special teams. M.D.C. by location: main body 80, head/helmet 70, arms 55 each, legs 70 each. Mobility very good to good: -5% Climb, -10% Prowl, Swim, Acrobatics and similar. Like all the new Dead Boy armor it is complete environmental battle armor, space capable, with computer life support, a five-hour independent oxygen supply, a voice-actuated support computer, cooling, gas filtration, radiation shielding, heat shielding to 300 degrees C, a self-tinting visor with HUD, loudspeaker and helmet radio. A breach threatens life once the suit is below 15 M.D.C.', 'Rifts World Book 11: Coalition War Campaign p.99-100'),
('ca-4-standard-dead-boy-armor', 'CA-4 Standard Dead Boy Armor', 'rifts', 'armor', 20, NULL, 'Not available; exclusive to the CS military.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 100, 'The standard new-style Coalition infantry armor, worn by most soldiers and officers. M.D.C. by location: main body 100, head/helmet 70, arms 60 each, legs 80 each. Mobility good: -5% Climb, -20% Prowl, Swim, Acrobatics and similar. Complete environmental battle armor with the full new Dead Boy feature set (see CA-3 Light Dead Boy Armor).', 'Rifts World Book 11: Coalition War Campaign p.99-100'),
('ca-5-juicer-dead-boy-armor', 'CA-5 Juicer Dead Boy Armor', 'rifts', 'armor', 30, NULL, 'Not available; exclusive to the CS military.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 125, 'A heavier new-style Dead Boy armor for Coalition Juicers, issued with the CAJ-5 weapon arm. M.D.C. by location: main body 125, head/helmet 80, arms 70 each, legs 85 each. Mobility good for a Juicer: -5% Climb, -20% Prowl, Swim, Acrobatics and similar; anyone who is not a Juicer, Crazy, full conversion cyborg or supernaturally strong is -15% and -30% instead. Complete environmental battle armor with the full new Dead Boy feature set (see CA-3 Light Dead Boy Armor).', 'Rifts World Book 11: Coalition War Campaign p.99-101'),
('caj-5-weapon-arm', 'CAJ-5 Weapon Arm', 'rifts', 'weapon', 15, NULL, 'Not available; exclusive to the CS military.', 'Plasma blaster 4D6 M.D.; light laser tool 4D6 S.D.C., 1D4 M.D. or 1D6 M.D.; vibro-blade tri-claw 3D6 M.D.', 1, 'Plasma blaster and laser tool 800 feet (244 m)', 'Plasma blaster 10 shots per standard E-Clip, or 50 from a hip or backpack energy pack (10 lbs); laser tool 20 shots per standard E-Clip', 'As an energy rifle', NULL, NULL, NULL, 'A detachable forearm weapon system issued to Coalition Juicers with the CA-5 armor, and usable with the CA-6 heavy armor: a plasma blaster, a three-setting cutting laser, and three vibro-blades that extend past the fist, retract to the knuckles for backhands, or fully extend as a triple-bladed sword.', 'Rifts World Book 11: Coalition War Campaign p.101-102'),
('ca-6c-cyborg-armor', 'CA-6C Cyborg Armor', 'rifts', 'armor', 60, NULL, 'Not available; exclusive to the CS military.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 200, 'Heavy plated infantry armor for the Cyborg Armored Division, worn by full conversion cyborgs and heavily reconstructed partial cyborgs, 6 ft 6 in to 7 ft 6 in (1.95-2.25 m) tall. M.D.C. by location: main body 200, head/helmet 100, arms 100 each, legs 120 each. Mobility fair to good for a full conversion cyborg: -15% Climb, -30% Prowl, Swim, Acrobatics and similar. No weapon systems of its own, but can be modified to take bionic ones. Helmet: HUD with up to six views, computer and video link by headjack, passive nightvision (2000 ft), telescopic (10x, 6000 ft), macro-lens (6x), thermo-imager (1000 ft), light filters, laser distancer (1000 ft effective, 2000 ft maximum) and laser targeting (+1 to strike to 1000 ft).', 'Rifts World Book 11: Coalition War Campaign p.102'),
('ca-6ex-exoskeleton-armor', 'CA-6EX Heavy Infantry Armor and Exoskeleton', 'rifts', 'armor', 60, NULL, 'Not available; exclusive to the CS military.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 200, 'The CA-6C plating built over a powered exoskeleton, so an ordinary strong human can wear it for heavy weapons, equipment and construction work; in effect a simple power armor. 6 ft 6 in to 7 ft 6 in tall. M.D.C. by location: main body 200, head/helmet 100, arms 100 each, legs 120 each. Exoskeleton bonuses: +8 P.S., +14 Spd, +10 ft (3 m) to leaps, fatigue at half the normal rate. Mobility good: -30% Prowl, -10% Swim, Acrobatics and similar, no Climb penalty. Helmet systems as the CA-6C.', 'Rifts World Book 11: Coalition War Campaign p.102'),
('ca-7-special-forces-dead-boy-armor', 'CA-7 Special Forces Heavy Dead Boy Armor', 'rifts', 'armor', 20, NULL, 'Not available; exclusive to the CS military. Unauthorized possession is treason and a death sentence.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 100, 'The black, spiked, skull-faced armor of the CS Special Forces, with the full new Dead Boy feature set. M.D.C. by location: main body 100, head/helmet 75, arms 60 each, legs 80 each. Mobility good: -5% Climb, -20% Prowl, Swim, Acrobatics and similar. Built in: a retractable vibro-knife on top of each forearm (1D6 M.D. each) and a garrote wire in the left wrist. Back mountings take a Special-Ops Mag-Five silent jet pack (max speed 60 mph/96.5 km, max altitude 1200 ft/365 m, runs on four standard CS E-Clips at 20 minutes of flight each) or an ammo drum or energy pack instead.', 'Rifts World Book 11: Coalition War Campaign p.103-104');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 20 Coalition War Campaign gear rows are in' AS assertion, count(*) AS got, 20 AS want
  FROM gear WHERE slug IN ('c-5-pump-pistol', 'c-20-laser-pistol', 'cp-30-laser-pulse-pistol', 'cp-40-pulse-laser-rifle', 'cp-50-dragonfire-assault-rifle', 'c-29-hellfire-plasma-cannon', 'cv-212-variable-frequency-laser-rifle', 'ctt-p40-particle-beam-cannon', 'ctt-m20-missile-rifle', 'cr-1-rocket-launcher', 'c-200-dead-mans-rail-gun', 'micro-fusion-rifle-grenade', 'giant-vibro-sword', 'ca-3-light-dead-boy-armor', 'ca-4-standard-dead-boy-armor', 'ca-5-juicer-dead-boy-armor', 'caj-5-weapon-arm', 'ca-6c-cyborg-armor', 'ca-6ex-exoskeleton-armor', 'ca-7-special-forces-dead-boy-armor');
SELECT 'and every one cites Coalition War Campaign' AS assertion, count(*) AS got, 20 AS want
  FROM gear WHERE source_book LIKE 'Rifts World Book 11: Coalition War Campaign p.%'
   AND slug IN ('c-5-pump-pistol', 'c-20-laser-pistol', 'cp-30-laser-pulse-pistol', 'cp-40-pulse-laser-rifle', 'cp-50-dragonfire-assault-rifle', 'c-29-hellfire-plasma-cannon', 'cv-212-variable-frequency-laser-rifle', 'ctt-p40-particle-beam-cannon', 'ctt-m20-missile-rifle', 'cr-1-rocket-launcher', 'c-200-dead-mans-rail-gun', 'micro-fusion-rifle-grenade', 'giant-vibro-sword', 'ca-3-light-dead-boy-armor', 'ca-4-standard-dead-boy-armor', 'ca-5-juicer-dead-boy-armor', 'caj-5-weapon-arm', 'ca-6c-cyborg-armor', 'ca-6ex-exoskeleton-armor', 'ca-7-special-forces-dead-boy-armor');

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-cwc-gear.sql');
